import pathlib,json,hashlib,subprocess,time
run='sllm-debug-20261109T163357Z-5a947f74';root=pathlib.Path('/data/brick1/boyjiang/glm5.1-fp8/debug')/run
files={}
def read(name):
 p=root/name;b=p.read_bytes();files[name]={'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()};return json.loads(b)
result=read('controller-result.json');start=read('controller-start.json');stack=read('stack.json')
unit=dict(x.split('=',1) for x in subprocess.check_output(['systemctl','show',run+'-controller.service','-p','MainPID,Result,ExecMainCode,ExecMainStatus,ExecMainStartTimestampMonotonic,ExecMainExitTimestampMonotonic,InvocationID,ExecStart,ActiveState,SubState'],text=True).splitlines())
assert unit['MainPID']=='0' and unit['Result']=='success' and unit['ExecMainStatus']=='0'
begin=int(unit['ExecMainStartTimestampMonotonic'])*1000;end=int(unit['ExecMainExitTimestampMonotonic'])*1000
assert 0<end-begin<=900*10**9 and result['success'] is True and result['publish_controller'] is False and result['model_service_pass'] is False
for role in ('worker','head'):
 e=result['exit_evidence'][role];assert e['normal_exit_verified'] and not e['final']['OOMKilled']
 assert not subprocess.check_output(['docker','ps','-aq','--no-trunc','--filter','id='+e['container_id']],text=True).strip()
assert result['exit_evidence']['worker']['final']['ExitCode']==0 and not result.get('monitor_errors')
out={'scope':'independent startup-control verification only; not GLM model service or controller supplement','run_id':run,'code_commit':'a9e17edb6f3d9393118ba4fb1c0d8acdbfdd1bf5','unit':unit,'unit_elapsed_s':(end-begin)/1e9,'monitor':{},'release':{}}
for name,dest in [('controller-monitor.jsonl','monitor'),('release60.jsonl','release')]:
 p=root/name;b=p.read_bytes();a=[json.loads(x) for x in b.splitlines()];files[name]={'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
 points=[x['monotonic_ns'] for x in a];spans=[(x['sample_end_ns']-x['sample_begin_ns'])/1e9 for x in a]
 assert len(a)>1 and all(begin<=x<=end for x in points) and max(spans)<=5 and all(0<y-x<=5*10**9 for x,y in zip(points,points[1:]))
 assert all(not x['gpu_processes'].strip() and all(int(line.split(',')[3].strip().split()[0])==0 for line in x['gpu'].splitlines()) for x in a)
 assert all(all(not int(line.split()[1]) for line in x['private_slice_memory_events'].splitlines() if line.split()[0].startswith('oom')) for x in a)
 if dest=='release':
  assert (points[-1]-points[0])/1e9>=60 and abs((points[-1]-points[0])/1e9-result['release_observation_s'])<1e-6
  assert all(all(y.get('absent') for y in x['containers'].values()) for x in a)
 stages={}
 for row in a:
  for label,t0,t1 in row['stage_timings_ns']:stages[label]=max(stages.get(label,0),(t1-t0)/1e9)
 out[dest]={'samples':len(a),'span_s':(points[-1]-points[0])/1e9,'maximum_sample_s':max(spans),'maximum_gap_s':max(y-x for x,y in zip(points,points[1:]))/1e9,'stage_maximum_s':stages}
proof_path=pathlib.Path('/run')/run/'guard-verification.json';raw=proof_path.read_bytes();proof=json.loads(raw)
assert proof_path.stat().st_uid==0 and proof_path.stat().st_mode&0o222==0 and proof['holder']==start['holder'] and proof['deadline_delay_seconds']==900
assert start['independent_controller_unit']['InvocationID']==unit['InvocationID']
out['guard']={'root_proof_path':str(proof_path),'sha256':hashlib.sha256(raw).hexdigest(),'deadline_delay_s':proof['deadline_delay_seconds'],'deadline_after_main_s':(int(proof['deadline_next_monotonic_usec'])*1000-begin)/1e9,'accuracy':subprocess.check_output(['systemctl','show',run+'-deadline.timer','-p','AccuracyUSec,NextElapseUSecMonotonic'],text=True),'arm_to_main_s':(begin-proof['armed_ns'])/1e9}
assert 0<out['guard']['deadline_after_main_s']<=900
(root/'guard-verification-preserved.json').write_bytes(raw);files['guard-verification-preserved.json']={'path':str(root/'guard-verification-preserved.json'),'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
out['result']=result;out['stack']=stack;out['files']=files;out['success']=True;out['model_service_pass']=False;out['historical_slow_sample_root_cause']='unresolved; no reproduction in this one sleep-only startup control'
p=root/'startup-independent-verification.json';b=(json.dumps(out,indent=2)+'\n').encode();p.write_bytes(b);print(json.dumps({'path':str(p),'sha256':hashlib.sha256(b).hexdigest(),'verification':out}))
